	CheckpointTokenUsage *agent.TokenUsage `json:"checkpoint_REDACTED_usage,omitempty"`

	// SubagentTokensBaseline is a snapshot of TokenUsage.SubagentTokens captured
	// at the last condensation reset. Subagent REDACTED usage is always re-read
	// from the start of each subagent transcript (agent IDs are discovered from
