		CheckpointID:     id.CheckpointID(info.CheckpointID),
		Strategy:         "manual-commit",
		CommitSHA:        info.CommitSha,
		CheckpointsCount: info.TotalSteps,
		FilesTouched:     info.FilesTouched,
		Sessions:         sessions,
