func matchCheckpointPrefix(lookup *explainCheckpointLookup, prefix string) []id.CheckpointID {
	var matches []id.CheckpointID
	for _, info := range lookup.committed {
		if strings.HasPrefix(info.CheckpointID.String(), prefix) {
